contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint lockTime, uint collectAmt) public payable {
        require(address(this).balance >= amount);
        require(lockTime >= 1);
        require(collectAmt >= 1 && collectAmt <= amount);

        // Set up: MinSum = 0 so only unlockTime can block the collect.
        c.SetMinSum(0);
        c.SetLogFile(address(this));

        uint balBefore = address(c).balance;
        c.Put{value: amount}(lockTime);
        uint balAfterPut = address(c).balance;
        (uint unlockTime, uint heldAfterPut) = c.Acc(address(this));

        // Preconditions observed from state: deposit recorded, unlock time in future.
        require(balAfterPut == balBefore + amount);
        require(heldAfterPut == amount);
        require(unlockTime > block.timestamp);

        // The deciding call: attempt to collect while locked.
        c.Collect(collectAmt);

        (, uint heldAfter) = c.Acc(address(this));
        assert(address(c).balance == balAfterPut && heldAfter == amount);
    }

    fallback() external payable {}
    receive() external payable {}
}

